insert into public.commitments (slug, title, title_sw, detail, source, source_url, made_on, due_on, sector, status, evidence) values
  ('school-feeding-dishi-na-county', 'Feed children in every public primary school (Dishi na County)', 'Kulisha watoto katika kila shule ya msingi ya umma (Dishi na County)', 'Campaign promise of free lunch in all public schools to raise transition from one level to the next. Delivered as Dishi na County: meals at a subsidised Sh5 for primary learners.', 'Campaign manifesto 2022 (12 mega projects)', 'https://www.kenyans.co.ke/news/78890-12-mega-projects-sakaja-promised-nairobi-residents', null, null, 'Education', 'in_progress', 'Reported in October 2025 to feed about 316,000 learners a day in more than 230 public primary schools and ECDE centres from 17 central kitchens. The county cabinet gave the programme legal backing in February 2026. Extending it to informal schools awaits funding. Sources: the-star.co.ke 2025-10-30, the-star.co.ke 2026-02-06.'),
  ('twenty-modern-markets', 'Build 20 new modern markets', 'Kujenga masoko mapya 20 ya kisasa', 'Promised in the 2022 campaign to decongest the main city markets. In August 2024 the governor restated the target as 20 markets by 2027.', 'Campaign rally, July 2022; restated August 2024', 'https://www.capitalfm.co.ke/news/2024/08/sakaja-pledges-20-modern-markets-in-nairobi-by-2027-to-boost-trade/', '2022-07-20', null, 'Trade', 'in_progress', 'Reported complete: Mwariro, Westlands, Karandini, Gikomba and Kangundo Road markets. Under construction include Mutuini and Kahawa West. The Auditor-General reported that Sh69.5 million was spent on Mutuini market while the project stalled. Sources: eastleighvoice.co.ke (Auditor-General on Mutuini), nairobi.go.ke.'),
  ('ward-biashara-fund', 'Sh50 million biashara fund every year for each of the 85 wards', 'Mfuko wa biashara wa Sh50 milioni kila mwaka kwa kila wadi kati ya 85', 'Campaign promise to fund small businesses in every ward. At Sh50 million for 85 wards this is about Sh4.25 billion a year.', 'Campaign, July 2022', 'https://www.the-star.co.ke/counties/nairobi/2022-07-28-igathe-sakaja-promise-better-services-for-nairobians-if-elected/', '2022-07-28', null, 'Trade', 'delayed', 'Implemented at a much smaller scale: in 2023 the county set aside Sh100 million in total for a revolving Biashara Fund for women, youth and people with disabilities across all wards. A Biashara Stimulus Programme was announced in November 2025 without a start date or amount. Sources: the-star.co.ke 2023-07-05, the-star.co.ke 2025-11-14.'),
  ('metro-commuter-rail', 'Build a city metro commuter rail to decongest the CBD', 'Kujenga reli ya abiria ya jiji ili kupunguza msongamano katikati ya jiji', 'Campaign and inauguration promise of a metro commuter light rail.', 'Inauguration, 25 August 2022', 'https://nairobinews.nation.africa/10-promises-governor-sakaja-made-to-nairobians/', '2022-08-25', null, 'Transport', 'in_progress', 'Planning stage only, no construction. The county cabinet approved phase 1 of the Nairobi Metropolitan Mass Rapid Transit System: a 30 km underground line from Eastlands to the CBD with 25 stations. The President endorsed it; financing is still being worked out and a project management unit is being set up. The whole programme is estimated at USD 7.78 billion. Sources: the-star.co.ke 2026-09-04, railjournal.com.'),
  ('boroughs-decentralise', 'Divide Nairobi into boroughs run by city managers to bring services closer', 'Kugawa Nairobi katika boroughs zinazoongozwa na mameneja ili kuleta huduma karibu', 'Campaign promise of five boroughs. A taskforce later recommended six: Central, Eastern, Western, Northern, Southern and South Eastern.', 'Campaign 2022; inauguration', 'https://www.the-star.co.ke/counties/nairobi/2023-05-28-sakajas-plan-to-subdivide-city-decentralise-services', '2022-08-25', null, 'Governance', 'in_progress', 'Six borough managers were appointed in November 2025 and met the governor for the first time on 4 December 2025. Each borough is meant to have one plan and one budget. Sources: the-star.co.ke 2025-11-18, the-star.co.ke 2025-12-04.'),
  ('clean-city-garbage', 'Keep Nairobi clean: fix garbage collection, e-waste and sewage', 'Kuweka Nairobi safi: ukusanyaji taka, taka za kielektroniki na maji taka', 'Inauguration promise of an e-waste handling system and sewerage works so sewage stops polluting streets.', 'Inauguration, 25 August 2022', 'https://nairobinews.nation.africa/10-promises-governor-sakaja-made-to-nairobians/', '2022-08-25', null, 'Environment', 'delayed', '24 new refuse trucks were flagged off and about 3,500 young people work as the Green Army. A county company, Green Nairobi, was created; its board was gazetted on 14 August 2026. In a podcast released on 2 September 2026 the governor himself named garbage among promises that have not been delivered. Sources: peopledaily.digital, citizen.digital.'),
  ('dandora-waste-to-energy', 'Turn Dandora dumpsite waste into 45 MW of electricity', 'Kubadilisha taka za Dandora kuwa umeme wa megawati 45', 'A project development agreement was signed with China National Electric Engineering Company on 19 September 2025. The power purchase agreement was still being finalised by the Ministry of Energy and EPRA.', 'Project agreement signing, 19 September 2025', 'https://businesstoday.co.ke/sakaja-seals-45mw-dandora-energy-deal/', '2025-09-19', null, 'Environment', 'delayed', 'In a podcast released on 2 September 2026 the governor named the Dandora waste-to-energy project as the promise that has not moved as planned. Source: peopledaily.digital.'),
  ('end-water-shortage-2026', 'End water shortages in Nairobi by 2026', 'Kumaliza uhaba wa maji Nairobi kufikia 2026', 'The governor said perennial water shortages would be history by 2026, mainly through the Northern Collector Tunnel.', 'Statement, 1 October 2023', 'https://www.the-star.co.ke/news/realtime/2023-10-01-nairobis-water-shortage-will-be-history-by-2026-sakaja', '2023-10-01', '2026-12-31', 'Water', 'in_progress', 'The Northern Collector Tunnel is complete and adds about 140 million litres a day. Reported demand is about 900 million litres a day against supply of about 525 million before the tunnel, so a gap remains. A second tunnel and the Maragua project are expected by 2027. Sources: citizen.digital, nation.africa.'),
  ('vocational-training-centres', 'Build and equip vocational training centres as skills hubs', 'Kujenga na kuandaa vyuo vya ufundi kama vituo vya ujuzi', 'Campaign promise to turn the county vocational training centres into technical and skills hubs.', 'Campaign, July 2022', 'https://www.the-star.co.ke/counties/nairobi/2022-07-28-igathe-sakaja-promise-better-services-for-nairobians-if-elected/', '2022-07-28', null, 'Education', 'in_progress', 'We found no public report of new centres completed. In September 2025 the Senate Education Committee summoned the governor over the state of ECDE and vocational centres after he cancelled an appearance. Source: capitalfm.co.ke 2025-09.'),
  ('county-blood-bank', 'Set up a county blood bank', 'Kuanzisha benki ya damu ya kaunti', 'Part of the 2022 health plan among the 12 mega projects.', 'Campaign manifesto 2022 (12 mega projects)', 'https://www.kenyans.co.ke/news/78890-12-mega-projects-sakaja-promised-nairobi-residents', null, null, 'Health', 'not_started', 'We found no public report that a county blood bank has been set up. Critics listed it among unmet promises in December 2025. Source: peopledaily.digital.'),
  ('single-business-permit', 'One electronic business permit instead of many licences', 'Kibali kimoja cha kielektroniki cha biashara badala ya leseni nyingi', 'Campaign promise to cut the number of licences, reduce corruption and raise revenue.', 'Campaign manifesto 2022 (12 mega projects)', 'https://www.kenyans.co.ke/news/78890-12-mega-projects-sakaja-promised-nairobi-residents', null, null, 'Trade', 'delivered', 'The Unified Business Permit started on 1 January 2024. It combines the business permit, fire, food hygiene, pest control, health and advertising licences, and is paid on NairobiPay (*647#). Source: the-star.co.ke 2024-01-01.'),
  ('ecde-classrooms-1500', 'Build 1,500 ECDE classrooms', 'Kujenga madarasa 1,500 ya ECDE', 'Restated by the governor as enrolment rose with school feeding. The national government is separately building about 5,000 classrooms in Nairobi.', 'Governor statement reported by Citizen Digital', 'https://citizen.digital/news/nairobi-governor-sakaja-reaffirms-commitment-to-ecde-classrooms-and-childcare-reforms-n349762', null, null, 'Education', 'in_progress', 'Construction reported as ongoing; we found no published count of classrooms finished. Source: citizen.digital.'),
  ('ward-funds-on-time', 'Pay ward development funds on time to all 85 wards', 'Kulipa fedha za maendeleo za wadi kwa wakati kwa wadi zote 85', 'Promised in the maiden address to the County Assembly on 19 October 2022.', 'Maiden address to the County Assembly, 19 October 2022', 'https://www.the-star.co.ke/counties/nairobi/2022-10-19-this-is-my-plan-for-nairobi-sakaja-says-in-maiden-assembly-speech/', '2022-10-19', null, 'Governance', 'in_progress', 'The allocation rose from Sh1.4 billion to Sh2 billion in 2023/24, but the governor told the Senate the county disbursed Sh715 million in 2022/23, Sh925 million in 2023/24 and Sh889 million in 2024/25. Sources: nairobi.go.ke, eastleighvoice.co.ke.'),
  ('sports-complex-every-subcounty', 'A modern sports complex in each of the 17 sub-counties', 'Uwanja wa kisasa wa michezo katika kila kaunti ndogo kati ya 17', 'Promise to build a sports facility in every sub-county.', 'Governor statement', 'https://www.mozzartsport.co.ke/football/news/governor-sakaja-promises-sophisticated-sports-complex-in-every-nairobi-sub-county/20399', null, null, 'Sports', 'in_progress', 'Dandora Stadium opened after a six-year delay at a cost of more than Sh276 million, and the Uhuru Complex sports arena opened in March 2024. Kihumbuini Stadium was reported more than 70 percent complete; Woodley and City Stadium are being upgraded. Sources: nairobi.go.ke, the-star.co.ke 2024-03-23, tv47.digital.'),
  ('affordable-housing-40000', '40,000 affordable homes through urban renewal of county estates', 'Nyumba 40,000 za bei nafuu kupitia ukarabati wa mitaa ya kaunti', 'Plan to redevelop old county estates, 70 percent of units affordable at Sh1.5 million to Sh3.5 million. Nine estates earmarked: Bahati, Maringo, Jericho, Lumumba, Ziwani, Bondeni, Kariobangi, Embakasi and Woodley.', 'Plan announced March 2023', 'https://www.the-star.co.ke/counties/nairobi/2023-03-08-how-sakaja-plans-to-set-up-40000-affordable-housing-units/', '2023-03-08', null, 'Housing', 'in_progress', 'The Jeevanjee and Bachelors project in Ngara reached 1,800 units, with phase one expected by August 2025. MCAs have called for a probe into stalled housing projects. Sources: the-star.co.ke 2025-05-30, eastleighvoice.co.ke.'),
  ('land-titling-2025', 'Complete land titling in Nairobi by 2025', 'Kukamilisha utoaji hati miliki za ardhi Nairobi kufikia 2025', 'Made while issuing 912 title deeds.', 'Title deed issuance event', 'https://eastleighvoice.co.ke/city-affairs/76645/sakaja-issues-912-title-deeds-vows-to-complete-nairobi-land-titling-by-2025', null, '2025-12-31', 'Lands', 'in_progress', '1,000 more title deeds were issued in September 2024. We found no report that titling was completed by the end of 2025. Source: the-star.co.ke 2024-09-19.'),
  ('ruto-sakaja-80bn-pact', 'Sh80 billion national and county cooperation agreement for roads, water, power, sanitation and waste', 'Makubaliano ya ushirikiano ya Sh80 bilioni kwa barabara, maji, umeme, usafi na taka', 'Signed by President Ruto and Governor Sakaja on 17 February 2026.', 'Cooperation agreement, 17 February 2026', 'https://www.the-star.co.ke/news/2026-02-17-ruto-sakajas-shh80bn-deal-to-transform-nairobi', '2026-02-17', null, 'Infrastructure', 'in_progress', 'The Senate recommended suspending the agreement over governance concerns, and an Assembly committee asked for a full list of projects within 30 days. A court challenge was filed. Sources: nairobilawmonthly.com, eastleighvoice.co.ke, nation.africa.')
